              sequencesEnabled={sequencesEnabled}
              setSequencesEnabled={setSequencesEnabled}
              sequenceGroupHeadersEnabled={sequenceGroupHeadersEnabled}
              setSequenceGroupHeadersEnabled={setSequenceGroupHeadersEnabled}
              bulkAddTasksEnabled={bulkAddTasksEnabled}
              setBulkAddTasksEnabled={setBulkAddTasksEnabled}
              bulkOpsEnabled={bulkOpsEnabled}
              setBulkOpsEnabled={setBulkOpsEnabled}
              expensesEnabled={expensesEnabled}
              setExpensesEnabled={setExpensesEnabled}
              workspaceDataEnabled={workspaceDataEnabled}
