                          const locVal = cleanLocationText(currentFocusTarget.location || "");
                          const hasLoc = locVal && locVal.trim() !== "" && !locVal.toLowerCase().includes("no specified location") && !locVal.toLowerCase().includes("no location");

                          const isCollabsBlank = !currentFocusTarget.attendees && !currentFocusTarget.collaborator;

                          const isBuffer = !!currentFocus.isBuffer;
                          const bufferType = currentFocus.bufferType; // "before" | "after"
                          const isBeforeBuffer = isBuffer && bufferType === "before";
                          const isAfterBuffer = isBuffer && bufferType === "after";

                          const mainTaskTitle = cleanString(currentFocusTarget.title || "Untitled Task");
                          
                          // Determine the dynamic task title that the user is working on
