                          taskFormPage === 2 
                            ? "bg-indigo-605 text-white shadow-md shadow-indigo-600/20 border-indigo-500/40"
                            : isDark
                              ? "text-indigo-400 hover:text-indigo-300 hover:bg-indigo-550/5"
                              : "text-indigo-600 hover:text-indigo-800 hover:bg-indigo-550/5"
