                                        isDark 
                                          ? "bg-slate-950 border-emerald-500/25 text-emerald-400 hover:border-emerald-400/50" 
                                          : "bg-emerald-50/50 border-emerald-200 text-emerald-800 hover:bg-emerald-100/50"
