                    const updatedList = savedAiPlans.map(p => p.id === updatedPlan.id ? updatedPlan : p);
                    saveAiPlansToStore(updatedList);
                    setShowEditPlanModal(false);
                    setEditingPlan(null);
                    triggerHaptic("success");
